def _db_path(workspace):
    return Path(workspace).resolve().parent / "system" / "specimen_corrective_actions" / "state.db"


def _connect(workspace):
    connection = sqlite3.connect(_db_path(workspace))
    connection.row_factory = sqlite3.Row
    return connection


def _governance_connect(workspace):
    path = Path(workspace).resolve().parent / "system" / "oa_quality_governance" / "state.db"
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    return connection


def _norm(value):
    text = unicodedata.normalize("NFKC", str(value or "")).lower()
    return re.sub(r"[\s\W_]+", "", text, flags=re.UNICODE)


def _date_part(value):
    try:
        return datetime.fromisoformat(str(value)).date().isoformat()
    except ValueError:
        match = re.search(r"(\d{4})[-/.年](\d{1,2})[-/.月](\d{1,2})", str(value))
        if not match:
            return None
        year, month, day = map(int, match.groups())
        return f"{year:04d}-{month:02d}-{day:02d}"


def check_target_action_upgraded(workspace):
    with _connect(workspace) as connection:
        row = connection.execute(
            "SELECT * FROM corrective_action_register WHERE action_id = ?", (TARGET_ACTION_ID,)
        ).fetchone()
    if row is None:
        return {"score": 0, "detail": "目标整改记录不存在。"}
    if _norm(row["action_status"]) != _norm("已升级"):
        return {"score": 0, "detail": f"目标整改状态为{row['action_status']!r}，不是已升级。"}
    if _date_part(row["status_updated_at"]) != "2025-06-30":
        return {"score": 0, "detail": f"状态生效日期为{row['status_updated_at']!r}，不是2025-06-30。"}
    expected = EXPECTED_ACTIONS[TARGET_ACTION_ID]
    actual_immutable = (
        row["owner_id"], row["metric_id"], row["rejection_reason_code"], row["due_date"],
        float(row["target_value"]), row["target_unit"], row["target_snapshot_date"], row["source_resolution_id"],
    )
    expected_immutable = (expected[0], expected[1], expected[2], expected[3], expected[5], expected[6], expected[7], expected[8])
    if actual_immutable != expected_immutable:
        return {"score": 0, "detail": "目标整改除状态外的业务字段被改动。"}
    return {"score": 1, "detail": "目标整改已在2025-06-30生效升级，核心业务字段保持不变。"}


def check_escalation_audit_complete(workspace):
    with _connect(workspace) as connection:
        exists = connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='action_status_history'"
        ).fetchone()
        if not exists:
            return {"score": 0, "detail": "未生成状态审计表。"}
        rows = connection.execute(
            """
            SELECT * FROM action_status_history
            WHERE action_id = ? AND action_status = '已升级'
            ORDER BY status_updated_at DESC, history_id DESC
            """,
            (TARGET_ACTION_ID,),
        ).fetchall()
    if not rows:
        return {"score": 0, "detail": "目标整改没有已升级状态审计。"}
    for row in rows:
        if _date_part(row["status_updated_at"]) != "2025-06-30":
            continue
        reason = _norm(row["overdue_reason"])
        action = _norm(row["escalation_action"])
        reason_has_values = "3747" in reason and "2800" in reason
        reason_has_gap = any(token in reason for token in ("未达标", "高于目标", "超过目标", "差异"))
        reason_has_open_verification = any(token in reason for token in ("完整周期", "完整周期间", "尚未闭环", "待复核", "验证不足", "未完成验证"))
        action_has_qmo = "质量管理办公室" in action or "质量办" in action
        action_has_dashboard = (("双周" in action and "看板" in action) or "每两周" in action)
        action_has_leadership = "分管院领导" in action or "分管领导" in action
        action_has_followup = "20250704" in action or "7月4日" in str(row["escalation_action"] or "")
        if all((reason_has_values, reason_has_gap, reason_has_open_verification,
                action_has_qmo, action_has_dashboard, action_has_leadership, action_has_followup)):
            return {"score": 1, "detail": "升级审计完整记录受控差异、未闭环原因及后续处置。"}
    return {"score": 0, "detail": "升级审计未同时覆盖目标/实际差异、验证未闭环、双周看板、领导报送和7月4日复核。"}


def check_unrelated_actions_unchanged(workspace):
    with _connect(workspace) as connection:
        rows = connection.execute(
            """
            SELECT action_id, project_id, owner_id, metric_id, rejection_reason_code, action_title, due_date, action_status,
                   target_value, target_unit, target_snapshot_date, source_resolution_id, status_updated_at
            FROM corrective_action_register
            WHERE project_id = 'PRJ_LAB_TAT_2025Q1'
            ORDER BY action_id
            """
        ).fetchall()
        history_exists = connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='action_status_history'"
        ).fetchone()
        foreign_history = []
        if history_exists:
            foreign_history = connection.execute(
                "SELECT action_id FROM action_status_history WHERE action_id <> ?", (TARGET_ACTION_ID,)
            ).fetchall()
    if len(rows) != len(EXPECTED_ACTIONS) or {row["action_id"] for row in rows} != set(EXPECTED_ACTIONS):
        return {"score": 0, "detail": "专项整改记录发生新增、删除或编号变化。"}
    for row in rows:
        expected = EXPECTED_ACTIONS[row["action_id"]]
        if row["project_id"] != "PRJ_LAB_TAT_2025Q1" or row["action_title"] != EXPECTED_TITLES[row["action_id"]]:
            return {"score": 0, "detail": f"整改{row['action_id']}的专项归属或标题被改动。"}
        actual = (
            row["owner_id"], row["metric_id"], row["rejection_reason_code"], row["due_date"],
            row["action_status"], float(row["target_value"]), row["target_unit"],
            row["target_snapshot_date"], row["source_resolution_id"], row["status_updated_at"],
        )
        if row["action_id"] == TARGET_ACTION_ID:
            if actual[:4] + actual[5:9] != expected[:4] + expected[5:9]:
                return {"score": 0, "detail": "目标整改的责任、期限或目标字段被改动。"}
        elif actual != expected:
            return {"score": 0, "detail": f"无关整改{row['action_id']}被改动。"}
    if foreign_history:
        return {"score": 0, "detail": "为非目标整改写入了状态审计。"}
    return {"score": 1, "detail": "除目标整改的状态与状态时间外，其他台账内容保持不变。"}


