        meeting = connection.execute(
            """
            SELECT meeting_id, meeting_date, approval_status, finalized_at
            FROM governance_meetings WHERE project_id = 'PRJ_LAB_TAT_2025Q1'
            """
        ).fetchall()
        resolutions = connection.execute(
            """
            SELECT r.resolution_id, r.owner_id, r.resolution_no, r.action_seq, r.action_title,
                   r.target_value, r.effective_date, r.due_date, r.final_flag,
                   r.owner_confirmation_status, r.source_document_version
            FROM meeting_resolutions r
            JOIN governance_meetings m ON m.meeting_id = r.meeting_id
            WHERE m.project_id = 'PRJ_LAB_TAT_2025Q1'
              AND r.resolution_type = 'final_action' AND r.final_flag = 1
